    edges = 0
    adj = {}
    in_degree = {}
    for c, target in mapping.items():
        if c != target:
            edges += 1
            adj[c] = target
            in_degree[target] = in_degree.get(target, 0) + 1

    # Count the number of pure cycles in the directed graph
    cycles = 0
    visited = set()

    for node in adj:
        if node not in visited:
            curr = node
            path_set = set()
            while curr in adj and curr not in visited:
                visited.add(curr)
                path_set.add(curr)
                curr = adj[curr]

            # If we loop back to a node in the current traversal path, a cycle is found
            if curr in path_set:
                # Find all nodes in this cycle
                cycle_nodes = set()
                temp = curr
                while True:
                    cycle_nodes.add(temp)
                    temp = adj[temp]
                    if temp == curr:
                        break

                # A cycle needs an extra operation if and only if it's a "pure" cycle.
                # A pure cycle has no incoming edges from outside the cycle.
                # Since every node in the cycle has 1 incoming edge from the cycle itself,
                # any in_degree > 1 means there is an incoming edge from outside.
                is_pure = True
                for n in cycle_nodes:
                    if in_degree.get(n, 0) > 1:
                        is_pure = False
                        break

                if is_pure:
                    cycles += 1

    # Minimum operations = (number of transition edges) + (number of pure cycles to break)
    print(edges + cycles)

